import { ROUTES, CONNECTIONS, POLICY_PRESETS, SEED_TOOLS, TOUR } from './data.js';
import { STATUS, escapeHTML as esc, agentById, agentName, canEdit, canApprove, DEMO_REVIEWER, formatUSD, findings, hasConnection, openApprovals, previewImpact, sampleModels, toolsForAgent, totalSpend } from './domain.js';
import {icon as I} from './icons.js';

const safe = esc;
export function statusPill(status,mini=false){const s=STATUS[status]||STATUS.missing;return `<span class="pill${mini?' mini':''}" data-status="${status}">${I(s.icon,mini?11:13)}${s.label}</span>`;}
export function connectionDots(agent){return `<span class="mini-coverage" aria-label="Connections: ${['A','B','C'].map(k=>agent.connections.includes(k)?k+' enabled':k+' unavailable').join(', ')}">${['A','B','C'].map(k=>`<span class="${agent.connections.includes(k)?'on':''}" title="${k}: ${agent.connections.includes(k)?'Connected':'Not connected'}">${k}</span>`).join('')}</span>`;}
function pageHeading(eyebrow,title,subtitle='',actions=''){return `<header class="page-heading"><div><div class="page-eyebrow"><span class="mini-line"></span>${safe(eyebrow)}</div><h1>${safe(title)}</h1>${subtitle?`<p>${safe(subtitle)}</p>`:''}</div>${actions?`<div class="page-actions">${actions}</div>`:''}</header>`;}
function btn(label,action,{variant='',icon='',data='',disabled=false,small=false}={}){return `<button type="button" class="btn ${variant} ${small?'tiny':''}" data-action="${action}" ${data} ${disabled?'disabled':''}>${icon?I(icon,15):''}${safe(label)}</button>`;}
function fullAgentLink(agent){return `#/agent/${encodeURIComponent(agent.id)}`;}
function personBadge(agent){return `<div class="avatar ${safe(agent.accent||'mint')}" aria-hidden="true">${safe(agent.initials)}</div>`;}
function agentRow(agent){return `<div class="agent-row">${personBadge(agent)}<div class="agent-info"><a href="${fullAgentLink(agent)}" class="agent-name">${safe(agent.name)}</a><div class="agent-small">${safe(agent.team)} · ${safe(agent.owner)}</div></div><div class="agent-right">${connectionDots(agent)}<span class="pill pill-outlined mini">${agent.mode==='observe'?'Observe':agent.mode==='enforce'?'Enforce':'Paused'}</span><a class="icon-btn" aria-label="Open ${safe(agent.name)}" href="${fullAgentLink(agent)}">${I('chevron',16)}</a></div></div>`;}
function eventSmall(event,state){return `<div class="activity-item"><span class="activity-glyph">${I(STATUS[event.status]?.icon||'info',16)}</span><div class="activity-body"><div class="space-between"><span class="activity-line">${safe(event.action)}</span>${statusPill(event.status,true)}</div><div class="activity-note">${safe(agentName(state,event.agent))} · ${safe(event.kind==='tool'?'Tool execution':'Model request')} · <button class="text-link" data-action="open-event" data-id="${safe(event.id)}">See why</button></div></div></div>`;}
export function renderAppShell(state,ui,route,content){
  const nav=ROUTES.filter(x=>x.group==='main');const secondary=ROUTES.filter(x=>x.group==='secondary');const current=route==='agent'?'catalog':route;
  const renderNav=x=>`<a href="#/${x.id}" class="nav-link" ${current===x.id?`aria-current="page"`:''}><span class="nav-icon">${I(x.icon,18)}</span>${x.text}${x.id==='approvals'&&openApprovals(state).length?`<span class="nav-count">${openApprovals(state).length}</span>`:''}</a>`;
  const routeTitle=route==='agent'?'Agent details':ROUTES.find(r=>r.id===route)?.text||'Overview';
  const tour=state.tour>=0&&state.tour<TOUR.length?TOUR[state.tour]:null;
  const tourBar=tour?`<div class="tour-bar" role="region" aria-label="Guided tour step ${state.tour+1} of ${TOUR.length}"><div class="tour-progress" aria-hidden="true">${TOUR.map((_,i)=>`<span class="${i<=state.tour?'done':''}"></span>`).join('')}</div><div class="tour-body"><strong>${safe(tour.title)}</strong><span>${safe(tour.note)}</span></div>${btn(state.tour===TOUR.length-1?'Finish tour':'Next', 'tour-next',{variant:'primary',small:true,icon:'arrow'})}<button class="icon-btn" data-action="tour-end" aria-label="Exit tour">${I('x',17)}</button></div>`:'';
  return `<div class="app-shell ${ui.navOpen?'nav-open':''}"><aside class="sidebar" id="sidebar" aria-label="Primary navigation"><a class="sidebar-brand" href="#/home"><span class="brand-symbol"><span></span></span><span><span class="brand-name">Agent Governance</span><span class="brand-sub">Workspace</span></span></a><nav class="nav-section" aria-label="Workspace"><div class="nav-label">Workspace</div>${nav.map(renderNav).join('')}</nav><nav class="nav-section" aria-label="Connections"><div class="nav-label">Set up</div>${secondary.map(renderNav).join('')}</nav><div class="sidebar-end"><div class="sidebar-divider"></div><button class="nav-link" style="width:100%" data-action="open-settings"><span class="nav-icon">${I('sliders',18)}</span>Appearance</button><div class="workspace-chip"><span class="workspace-icon">D</span><span><strong style="display:block;color:var(--text);font-size:12px">Demo workspace</strong>Sample data only</span></div><div class="sidebar-footer">Explore the product. Nothing here connects to your systems.</div></div></aside><button class="nav-backdrop" data-action="close-nav" aria-label="Close navigation"></button><div class="main-area"><header class="topbar"><button class="icon-btn menu-btn" data-action="toggle-nav" aria-controls="sidebar" aria-expanded="${ui.navOpen?'true':'false'}" aria-label="Open menu">${I('menu',20)}</button><span class="crumb">Workspace / <strong>${safe(routeTitle)}</strong></span><div class="topbar-right"><span class="demo-pill" title="All activity and keys are simulated"><span class="demo-dot"></span>Interactive demo</span><label class="role-picker"><span>View as</span>${I('users',13)}<select id="role-select" aria-label="Preview role"><option value="operator" ${state.role==='operator'?'selected':''}>Operator</option><option value="approver" ${state.role==='approver'?'selected':''}>Approver</option><option value="auditor" ${state.role==='auditor'?'selected':''}>Auditor</option></select></label><button class="icon-btn" data-action="open-help" aria-label="About this demo" title="About this demo">${I('help',19)}</button></div></header>${tourBar}<main class="page-content" id="main" tabindex="-1">${content}</main></div></div>${renderDrawer(state,ui)}${renderModal(state,ui)}${ui.toast?`<div class="toast" role="status">${I('check',15)}${safe(ui.toast)}</div>`:''}`;
}
export function pageHome(state){
  const open=openApprovals(state).length;const recent=state.events.slice(0,4);
  return `<div class="hero"><div class="hero-main"><div class="hero-kicker">Your agent workspace</div><h1>Every agent.<br>One clear view.</h1><p>See what your agents do, understand each decision, and step in when it matters.</p><div class="flex gap-2">${btn('Explore agents','navigate',{variant:'primary',icon:'arrow',data:'data-route="catalog"'})}${btn('Take a quick tour','tour-start',{icon:'play'})}</div></div><div class="hero-art" aria-hidden="true"><div class="orbit"><div class="orbit-core">${I('shield-check',51)}</div><span class="orbit-node one">${I('activity',19)}</span><span class="orbit-node two">${I('users',19)}</span><span class="orbit-node three">${I('check',19)}</span></div></div></div>
  ${open?`<div class="banner">${I('clock',19)}<div class="banner-content"><strong>${open} actions need a review.</strong> No connected tool will run until an authorized person decides.</div><a href="#/approvals" class="btn tiny">View requests ${I('arrow',14)}</a></div>`:''}
  <div class="stat-grid"><div class="card stat-card"><div class="stat-top">Agents <span class="stat-icon">${I('layers',17)}</span></div><div class="stat-value">${state.agents.length}</div><div class="stat-foot">In your catalog</div></div><div class="card stat-card"><div class="stat-top">Requests observed <span class="stat-icon">${I('activity',17)}</span></div><div class="stat-value">${state.agents.reduce((n,a)=>n+a.requests,0).toLocaleString('en-US')}</div><div class="stat-foot">Sample reporting period</div></div><div class="card stat-card"><div class="stat-top">AI spending <span class="stat-icon">${I('wallet',17)}</span></div><div class="stat-value">${formatUSD(totalSpend(state))}</div><div class="stat-foot">Sample daily total</div></div></div>
  <div class="grid-2 mt-6"><section class="card card-pad"><div class="card-title-row"><div><h2 class="card-title">Your agents</h2><p class="card-subtitle">Their mode and connected protections</p></div><a href="#/catalog" class="btn tiny">View catalog ${I('arrow',13)}</a></div>${state.agents.slice(0,4).map(agentRow).join('')}</section><section class="card card-pad"><div class="card-title-row"><div><h2 class="card-title">Recent decisions</h2><p class="card-subtitle">What happened, in plain language</p></div><a href="#/activity" class="btn tiny">All activity ${I('arrow',13)}</a></div>${recent.map(e=>eventSmall(e,state)).join('')}</section></div>
  <div class="section-head"><div><h2>Start with what matters</h2><p>Three steps. More control whenever you need it.</p></div></div><div class="grid-3"><a class="card card-tight" href="#/catalog"><div class="space-between"><span class="stat-icon">${I('layers',18)}</span>${I('arrow',16)}</div><h3 style="font-size:14px;margin:20px 0 5px">1. Know your agents</h3><p class="muted small" style="margin:0">See owners, tools and connections.</p></a><a class="card card-tight" href="#/activity"><div class="space-between"><span class="stat-icon">${I('activity',18)}</span>${I('arrow',16)}</div><h3 style="font-size:14px;margin:20px 0 5px">2. See what happened</h3><p class="muted small" style="margin:0">Review decisions without reading logs.</p></a><a class="card card-tight" href="#/rules"><div class="space-between"><span class="stat-icon">${I('shield-check',18)}</span>${I('arrow',16)}</div><h3 style="font-size:14px;margin:20px 0 5px">3. Choose the rules</h3><p class="muted small" style="margin:0">Preview changes before enforcement.</p></a></div>`;
}
export function pageCatalog(state,ui){
  const tab=ui.catalogTab||'agents';const q=(ui.catalogSearch||'').toLowerCase().trim();const agentList=state.agents.filter(a=>`${a.name} ${a.owner} ${a.team}`.toLowerCase().includes(q));const toolList=SEED_TOOLS.filter(t=>`${t.name} ${t.type} ${agentName(state,t.agent)}`.toLowerCase().includes(q));
  const actions=canEdit(state)?btn('Add agent','add-agent',{variant:'primary',icon:'plus'}):'';
  let body='';
  if(tab==='agents') body=agentList.length?`<div class="agent-grid">${agentList.map(a=>`<article class="card agent-card"><div class="agent-card-head">${personBadge(a)}<span class="pill pill-outlined mini">${a.mode==='observe'?'Observe':a.mode==='enforce'?'Enforce':'Paused'}</span></div><h3>${safe(a.name)}</h3><p>${safe(a.team)} · ${safe(a.owner)}</p><div class="agent-card-footer">${connectionDots(a)}<a href="${fullAgentLink(a)}" class="btn tiny">Open ${I('arrow',13)}</a></div></article>`).join('')}</div>`:empty('No matching agents','Try a different name or owner.');
  if(tab==='tools')body=toolList.length?`<div class="card table-scroll"><table class="table"><thead><tr><th>Tool</th><th>Agent</th><th>Type</th><th>Approval</th><th>Execution control</th></tr></thead><tbody>${toolList.map(t=>{const a=agentById(state,t.agent);const controlled=a?.connections.includes('B');return `<tr><td><strong>${safe(t.name)}</strong></td><td><a href="${fullAgentLink(a)}" class="text-link">${safe(a.name)}</a></td><td>${safe(t.type)}</td><td>${t.approved?statusPill('approved',true):statusPill('pending',true)}</td><td>${controlled?`<span class="pill mini" data-status="allowed">${I('check',11)}Through gateway</span>`:statusPill('outside',true)}</td></tr>`;}).join('')}</tbody></table></div>`:empty('No matching tools','Try another search.');
  if(tab==='models')body=`<div class="grid-3">${sampleModels.map(m=>`<div class="card card-pad"><span class="stat-icon">${I('sparkles',18)}</span><h3 style="font-size:16px;margin:20px 0 2px">${safe(m.name)}</h3><p class="muted small" style="margin:0 0 17px">${safe(m.provider)}</p><div class="space-between"><span class="small muted">Used by ${m.agentCount} demo agents</span>${I('check',15)}</div></div>`).join('')}</div>`;
  return `${pageHeading('Your workspace','Catalog','Everything connected to your agents, in one place.',actions)}<div class="toolbar"><div class="tabs" role="tablist" aria-label="Catalog sections">${[['agents','Agents'],['tools','Tools'],['models','Models']].map(([id,label])=>`<button role="tab" class="tab" data-action="catalog-tab" data-value="${id}" aria-selected="${id===tab}">${label}</button>`).join('')}</div><div class="grow"></div>${tab!=='models'?`<label class="input-wrap" style="width:min(300px,100%)">${I('search',17)}<input id="catalog-search" placeholder="Search ${tab}..." aria-label="Search ${tab}" value="${safe(ui.catalogSearch||'')}" /></label>`:''}</div>${body}`;
}
export function pageAgent(state,ui,id){
  const a=agentById(state,id);if(!a)return `${pageHeading('Catalog','Agent not found')}<a href="#/catalog" class="btn">Back to catalog</a>`;
  const events=state.events.filter(e=>e.agent===id).slice(0,4);const preset=POLICY_PRESETS.find(p=>p.id===a.preset);
  const modeBtn=canEdit(state)?`${btn(a.mode==='enforce'?'Switch to Observe':'Review Enforce mode','preview-enforce',{variant:a.mode==='enforce'?'':'primary',data:`data-id="${safe(a.id)}"`,icon:a.mode==='enforce'?'eye':'shield'})}${btn(a.mode==='suspended'?'Resume agent':'Pause agent','toggle-pause',{variant:a.mode==='suspended'?'':'danger',data:`data-id="${safe(a.id)}"`})}`:'';
  return `<div class="page-eyebrow"><a href="#/catalog" class="text-link">Catalog</a> ${I('chevron',12)} Agent details</div><div class="detail-head">${personBadge(a)}<div><h1>${safe(a.name)}</h1><p>${safe(a.team)} · Owned by ${safe(a.owner)}</p></div><div class="detail-actions">${modeBtn}</div></div><div class="detail-summary"><div class="detail-metric"><strong>${a.requests.toLocaleString('en-US')}</strong><span>Sample requests</span></div><div class="detail-metric"><strong>${formatUSD(a.spent)}</strong><span>Daily spending</span></div><div class="detail-metric"><strong>${a.connections.length} of 3</strong><span>Connections</span></div></div><div class="detail-grid"><div class="detail-stack"><section class="card card-pad"><div class="card-title-row"><div><h2 class="card-title">Connected protections</h2><p class="card-subtitle">Choose what you need. A is always on.</p></div><a href="#/integrations" class="btn tiny">Manage ${I('arrow',13)}</a></div><div class="connection-grid">${CONNECTIONS.map(c=>`<div class="connection-card ${hasConnection(a,c.id)?'connected':''}"><div class="connection-letter">${c.id}</div><div><h3>${safe(c.name)}</h3><p>${safe(c.id==='A'?'Model activity':c.id==='B'?'Actual tool calls':'Person-level access')}</p></div><span class="pill mini ${hasConnection(a,c.id)?'':'pill-outlined'}">${hasConnection(a,c.id)?'On':'Off'}</span></div>`).join('')}</div></section><section class="card card-pad"><div class="card-title-row"><div><h2 class="card-title">Recent activity</h2><p class="card-subtitle">From this agent</p></div><a href="#/activity" class="btn tiny">All activity ${I('arrow',12)}</a></div>${events.length?events.map(e=>eventSmall(e,state)).join(''):empty('No activity yet','Run a demo action to see an event.')}</section></div><div class="detail-stack"><section class="card card-pad"><h2 class="card-title">Rules and mode</h2><p class="card-subtitle">How this agent is protected</p><div class="separator"></div><div class="space-between mb-4"><strong class="small">Mode</strong><span class="pill pill-outlined">${a.mode==='observe'?`${I('eye',13)}Observe`:a.mode==='enforce'?`${I('shield',13)}Enforce`:`${I('pause',13)}Paused`}</span></div><p class="micro muted">${a.mode==='observe'?'Shows what rules would block, without applying those particular rules. Basic safeguards still apply.':a.mode==='enforce'?'Applies configured rules to requests that pass through the gateway.':'Requests through the gateway are stopped.'}</p><div class="separator"></div><div class="space-between mb-4"><strong class="small">Policy</strong><a href="#/rules" class="text-link small">${safe(preset.name)}</a></div><div class="space-between"><strong class="small">Tools</strong><span class="small muted">${toolsForAgent(id).length} discovered</span></div></section><section class="card card-pad"><h2 class="card-title">Try a demo action</h2><p class="card-subtitle">See how the current setup responds</p><div class="separator"></div><div class="step-list"><div class="step"><span class="step-number">1</span><div class="step-main"><strong>Model requests a critical tool</strong><p>See the decision in the inference channel.</p></div></div><div class="step"><span class="step-number">2</span><div class="step-main"><strong>Tool attempts to run</strong><p>See what changes with connection B.</p></div></div></div><div class="flex gap-2 mt-4">${btn('Test request','simulate',{variant:'primary',data:`data-id="${safe(a.id)}" data-channel="inference"`})}${btn('Test tool','simulate',{data:`data-id="${safe(a.id)}" data-channel="tool"`})}</div></section></div></div>`;
}
function empty(title,text,action=''){return `<div class="empty-state"><div class="empty-icon">${I('search',24)}</div><h3>${safe(title)}</h3><p>${safe(text)}</p>${action}</div>`;}
function filteredEvents(state,ui,forAudit=false){return state.events.filter(e=>{
  const q=(forAudit?ui.auditSearch:ui.activitySearch||'')?.toLowerCase().trim()||'';
  const matchSearch=!q||`${e.id} ${e.action} ${agentName(state,e.agent)} ${e.actor} ${e.rule} ${e.status}`.toLowerCase().includes(q);
  const matchAgent=forAudit||!ui.activityAgent||ui.activityAgent==='all'||e.agent===ui.activityAgent;
  const matchStatus=forAudit||!ui.activityStatus||ui.activityStatus==='all'||e.status===ui.activityStatus;
  const matchPause=forAudit||!ui.activityPaused||!ui.pausedIds||ui.pausedIds.has(e.id);
  return matchSearch&&matchAgent&&matchStatus&&matchPause;
});}
export function pageActivity(state,ui){
  const events=filteredEvents(state,ui);
  const actions=`${btn(ui.activityPaused?'Resume feed':'Pause feed','activity-pause',{icon:ui.activityPaused?'play':'pause'})}${btn('Try a risky action','simulate',{variant:'primary',icon:'bolt',data:'data-id="atlas" data-channel="inference"'})}`;
  return `${pageHeading('What is happening','Activity','See decisions as a story, not a wall of logs.',actions)}<div class="toolbar"><label class="input-wrap grow" style="max-width:350px">${I('search',17)}<input id="activity-search" value="${safe(ui.activitySearch||'')}" placeholder="Search activity" aria-label="Search activity" /></label><select class="field-select" id="activity-agent" aria-label="Filter by agent"><option value="all">All agents</option>${state.agents.map(a=>`<option value="${safe(a.id)}" ${ui.activityAgent===a.id?'selected':''}>${safe(a.name)}</option>`).join('')}</select><select class="field-select" id="activity-status" aria-label="Filter by decision"><option value="all">All decisions</option>${Object.entries(STATUS).filter(([k])=>!['approved','rejected'].includes(k)).map(([k,v])=>`<option value="${k}" ${ui.activityStatus===k?'selected':''}>${v.label}</option>`).join('')}</select></div>${ui.activityPaused?`<div class="banner">${I('pause',17)}<div class="banner-content"><strong>Feed paused.</strong> New demo events are queued until you resume.</div></div>`:''}<div class="card table-scroll"><table class="table"><thead><tr><th>Decision</th><th>What happened</th><th>Agent</th><th>Channel</th><th>Time</th><th></th></tr></thead><tbody>${events.map(e=>`<tr><td>${statusPill(e.status)}</td><td><button class="row-link" data-action="open-event" data-id="${safe(e.id)}">${safe(e.action)}</button><span class="subtext">${safe(e.actor)} · ${safe(e.id)}</span></td><td>${safe(agentName(state,e.agent))}</td><td>${safe(e.kind==='tool'?'Tool':'Model')}</td><td class="nowrap">${safe(e.at)}</td><td><button class="icon-btn" data-action="open-event" data-id="${safe(e.id)}" aria-label="Explain ${safe(e.id)}">${I('chevron',16)}</button></td></tr>`).join('')}</tbody></table>${events.length?'':empty('No matching events','Clear your filters to see more activity.',btn('Clear filters','clear-activity'))}</div><div class="tip mt-4">${I('info',17)}<span><strong>Would block</strong> means a rule was evaluated without enforcing that particular decision. <strong>Not covered</strong> means actual tool execution could be outside the gateway.</span></div>`;
}
export function pageRules(state,ui){
  const a=agentById(state,ui.rulesAgent||state.selectedAgent)||state.agents[0];const preset=POLICY_PRESETS.find(p=>p.id===a.preset);
  const action=btn('How rules work','open-explainer',{icon:'help',data:'data-topic="rules"'});
  const impact=previewImpact(state,a.id);
  return `${pageHeading('Choose the guardrails','Rules','Simple defaults first. More detail only when you need it.',action)}<div class="toolbar"><label class="flex-center gap-2 small meta-strong" for="rules-agent">For agent</label><select class="field-select" id="rules-agent">${state.agents.map(x=>`<option value="${safe(x.id)}" ${a.id===x.id?'selected':''}>${safe(x.name)}</option>`).join('')}</select><span class="pill pill-outlined">${a.mode==='observe'?'Observe mode':a.mode==='enforce'?'Enforce mode':'Agent paused'}</span></div><div class="section-head"><h2>Start with a policy</h2></div><div class="policy-grid">${POLICY_PRESETS.map(p=>`<button type="button" class="policy-card ${a.preset===p.id?'selected':''}" data-action="choose-preset" data-id="${safe(a.id)}" data-value="${p.id}" ${canEdit(state)?'':'disabled'} aria-pressed="${a.preset===p.id}"><span class="policy-num">OPTION 0${p.id}</span>${a.preset===p.id?`<span class="chosen">${I('check-circle',19)}</span>`:''}<h3>${safe(p.name)}</h3><p>${safe(p.subtitle)}</p></button>`).join('')}</div><div class="grid-2 mt-6"><section class="card card-pad"><div class="card-title-row"><div><h2 class="card-title">Before you turn rules on</h2><p class="card-subtitle">A preview based on sample requests</p></div>${statusPill('would_block',true)}</div><div class="space-between mb-4"><div><div class="stat-value" style="margin:0">${impact.count}</div><div class="small muted">Requests that would be blocked in this sample</div></div><span class="stat-icon" style="width:49px;height:49px">${I('eye',23)}</span></div>${impact.actions.length?`<div class="step-list">${impact.actions.slice(0,3).map(x=>`<div class="step"><span class="step-number">${I('eye',14)}</span><div class="step-main"><strong>${safe(x)}</strong><p>Evaluated, not blocked in Observe mode</p></div></div>`).join('')}</div>`:`<div class="tip">${I('info',16)}No recent would-block decisions for this agent. This is not proof that there is no risk.</div>`}<div class="flex gap-2 mt-4">${btn(a.mode==='enforce'?'Return to Observe':'Review Enforce mode','preview-enforce',{variant:'primary',data:`data-id="${safe(a.id)}"`,disabled:!canEdit(state)})}${btn('Test risky action','simulate',{data:`data-id="${safe(a.id)}" data-channel="inference"`})}</div></section><section class="card card-pad"><div class="card-title-row"><h2 class="card-title">Current policy</h2>${btn('Details','open-explainer',{variant:'ghost',icon:'info',small:true,data:`data-topic="preset${a.preset}"`})}</div><div class="tip">${I('shield-check',18)}<div><strong>${safe(preset.name)}</strong><div style="margin-top:5px">${safe(preset.summary)}</div></div></div><div class="section-head"><h2>What can this agent do?</h2></div><div class="step-list"><div class="step"><span class="step-number">${I('check',15)}</span><div class="step-main"><strong>Read</strong><p>Access permitted data under the policy</p></div></div><div class="step"><span class="step-number">${I('info',15)}</span><div class="step-main"><strong>Write</strong><p>${a.preset===1?'Allowed when approved; can be monitored.':'Requires additional permissions and identity, depending on the policy.'}</p></div></div><div class="step"><span class="step-number">${I('lock',15)}</span><div class="step-main"><strong>Critical actions</strong><p>${a.preset===1?'Denied in Enforce mode.':'Denied unless all required safeguards are present.'}</p></div></div></div></section></div>`;
}
export function pageApprovals(state){
  const pending=openApprovals(state);const resolved=state.approvals.filter(a=>a.status!=='pending');
  return `${pageHeading('Human oversight','Approvals','Review important actions before they run.',btn('How approvals work','open-explainer',{icon:'help',data:'data-topic="approvals"'}))}${pending.length?`<div class="banner">${I('clock',18)}<div class="banner-content"><strong>${pending.length} waiting for a decision.</strong> A different, authorized person must review each request.</div></div>`:''}${pending.length?pending.map(a=>`<article class="card approval-card"><span class="approval-icon">${I('clock',22)}</span><div style="flex:1;min-width:180px"><div class="flex-center gap-2 mb-2">${statusPill('pending',true)}<span class="micro muted">${safe(a.id)}</span></div><h3>${safe(a.action)}</h3><p>${safe(a.reason)}</p><div class="approval-metadata"><span>${safe(agentName(state,a.agent))}</span><span>Requested by ${safe(a.requestedBy)}</span><span>Expires in ${safe(a.expires)} · simulated</span></div></div><div class="approval-actions">${btn('Reject','approval-confirm',{variant:'',small:true,data:`data-id="${safe(a.id)}" data-value="rejected"`,disabled:!canApprove(state)||!hasConnection(agentById(state,a.agent),'B')})}${btn('Approve','approval-confirm',{variant:'primary',small:true,data:`data-id="${safe(a.id)}" data-value="approved"`,disabled:!canApprove(state)||!hasConnection(agentById(state,a.agent),'B')})}</div></article>`).join(''):empty('All caught up','No actions are waiting for review. New requests will appear here.')}${canApprove(state)?`<div class="tip mt-4">${I('users',17)}<span>You are previewing the <strong>Approver</strong> role as ${safe(DEMO_REVIEWER)}. This is not real authentication.</span></div>`:''}${!canApprove(state)?`<div class="tip mt-4">${I('info',17)}<span>You’re previewing the <strong>${safe(state.role)}</strong> role. Switch to <strong>Approver</strong> in the top bar to try these decisions. This is a demo role switch, not authentication.</span></div>`:''}${resolved.length?`<div class="section-head"><h2>Recently reviewed</h2></div><div class="card card-tight">${resolved.map(a=>`<div class="agent-row"><div class="agent-info"><div class="agent-name">${safe(a.action)}</div><div class="agent-small">${safe(agentName(state,a.agent))} · ${safe(a.id)}</div></div>${statusPill(a.status)}</div>`).join('')}</div>`:''}`;
}
export function pageSpending(state){
  return `${pageHeading('Understand the costs','Spending','Usage by agent, with limits you can recognize.',btn('About these numbers','open-explainer',{icon:'help',data:'data-topic="spending"'}))}<div class="stat-grid"><div class="card stat-card"><div class="stat-top">Total today <span class="stat-icon">${I('wallet',18)}</span></div><div class="stat-value">${formatUSD(totalSpend(state))}</div><div class="stat-foot">Synthetic usage data</div></div><div class="card stat-card"><div class="stat-top">Daily budgets <span class="stat-icon">${I('gauge',18)}</span></div><div class="stat-value">${formatUSD(state.agents.reduce((n,a)=>n+a.budget,0))}</div><div class="stat-foot">Across demo agents</div></div><div class="card stat-card"><div class="stat-top">Requests <span class="stat-icon">${I('activity',18)}</span></div><div class="stat-value">${state.agents.reduce((n,a)=>n+a.requests,0).toLocaleString()}</div><div class="stat-foot">Sample reporting period</div></div></div><div class="grid-2 mt-6"><section class="card card-pad"><h2 class="card-title">Spending by agent</h2><p class="card-subtitle">Today · USD</p><div class="separator"></div>${state.agents.map(a=>{const pct=Math.min(100,Math.round((a.spent/a.budget)*100));return `<div class="budget-item"><div class="budget-top"><a href="${fullAgentLink(a)}" class="agent-name">${safe(a.name)}</a><span><strong>${formatUSD(a.spent)}</strong> / ${formatUSD(a.budget)}</span></div><div class="progress ${pct>=90?'danger':pct>=75?'warn':''}" role="progressbar" aria-label="${safe(a.name)} daily budget" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><span style="width:${pct}%"></span></div><div class="budget-note">${pct}% of daily limit${canEdit(state)?` · <button data-action="edit-budget" data-id="${safe(a.id)}" class="text-link">Edit limit</button>`:''}</div></div>`;}).join('')}</section><section class="card card-pad"><h2 class="card-title">Where the spend comes from</h2><p class="card-subtitle">Illustrative split by model</p><div class="separator"></div><div class="space-between mb-4"><strong class="small">GPT-6</strong><strong>${formatUSD(totalSpend(state)*.69)}</strong></div><div class="progress mb-6"><span style="width:69%"></span></div><div class="space-between mb-4"><strong class="small">Claude Sonnet</strong><strong>${formatUSD(totalSpend(state)*.31)}</strong></div><div class="progress"><span style="width:31%"></span></div><div class="tip mt-6">${I('users',16)}<div>Per-person costs need <strong>connection C</strong>. Without a verified user identity, spending stays attributed to the agent.</div></div></section></div>`;
}
export function pageAudit(state,ui){
  const events=filteredEvents(state,ui,true);
  return `${pageHeading('Find the reason','Audit','Trace a decision back to what happened and why.',btn('How evidence works','open-explainer',{icon:'help',data:'data-topic="audit"'}))}<div class="toolbar"><label class="input-wrap grow" style="max-width:480px">${I('search',17)}<input id="audit-search" aria-label="Search audit records" placeholder="Search by trace, agent, action or rule" value="${safe(ui.auditSearch||'')}"></label>${btn('Clear','clear-audit',{icon:'x'})}</div><div class="card table-scroll"><table class="table"><thead><tr><th>Record</th><th>Action</th><th>Decision</th><th>Evidence</th><th></th></tr></thead><tbody>${events.map(e=>`<tr><td class="mono">${safe(e.id)}</td><td><button class="row-link" data-action="open-event" data-id="${safe(e.id)}">${safe(e.action)}</button><span class="subtext">${safe(agentName(state,e.agent))} · ${safe(e.at)}</span></td><td>${statusPill(e.status,true)}</td><td>${e.evidence?`<span class="pill mini" data-status="allowed">${I('check',11)}Sample record</span>`:statusPill('missing',true)}</td><td><button class="icon-btn" aria-label="Open audit record ${safe(e.id)}" data-action="open-event" data-id="${safe(e.id)}">${I('chevron',16)}</button></td></tr>`).join('')}</tbody></table>${!events.length?empty('No records match','Try a trace ID or a different action.'):''}</div><div class="tip mt-4">${I('info',16)}This demo visualizes an audit trail. It does not prove immutable storage, retention, or integrity of real records.</div>`;
}
export function pageIntegrations(state,ui){
  const a=agentById(state,ui.integrationAgent||state.selectedAgent)||state.agents[0];
  return `${pageHeading('Add more control','Integrations','Start with AI requests. Add tool control or user identity when you need them.')}
  <div class="toolbar"><label for="integration-agent" class="small meta-strong">Preview for</label><select id="integration-agent" class="field-select">${state.agents.map(x=>`<option value="${safe(x.id)}" ${x.id===a.id?'selected':''}>${safe(x.name)}</option>`).join('')}</select><span class="pill pill-outlined">Demo configuration</span></div>
  <div class="integration-grid">${CONNECTIONS.map((c,i)=>`<article class="card integration-card"><div class="integration-id"><span class="letter">${c.id}</span>${hasConnection(a,c.id)?`<span class="pill mini" data-status="allowed">${I('check',11)}On in demo</span>`:`<span class="pill pill-outlined mini">Optional</span>`}</div><h2>${safe(c.name)}</h2><p>${safe(c.description)}</p><div class="button-row">${btn('How it works','open-connection',{data:`data-id="${c.id}"`,icon:'arrow'})}${c.id!=='A'&&canEdit(state)?btn(hasConnection(a,c.id)?'Remove':'Enable demo','toggle-connection',{variant:hasConnection(a,c.id)?'':'primary',data:`data-id="${c.id}" data-agent="${safe(a.id)}"` }):''}</div></article>`).join('')}</div><div class="section-head"><div><h2>What changes when you connect more?</h2><p>Capabilities depend on which path the request takes.</p></div></div><div class="card card-pad"><div class="step-list"><div class="step"><span class="step-number">A</span><div class="step-main"><strong>With A: observe model requests</strong><p>See model usage, tool intentions, and decisions on the inference channel.</p></div></div><div class="step"><span class="step-number">B</span><div class="step-main"><strong>With B: control tools before they run</strong><p>Check real tool parameters, withhold credentials, and stop execution. Local tools outside B are not covered.</p></div></div><div class="step"><span class="step-number">C</span><div class="step-main"><strong>With C: apply rules to real users</strong><p>Use verified identity for access and spending. Your app must forward a valid identity token.</p></div></div></div></div>`;
}
export function pageNotFound(){return `${pageHeading('Not found','This page isn’t available','Check the link or return to your workspace.')}<a class="btn primary" href="#/home">Go to overview ${I('arrow',15)}</a>`;}
export function renderPage(state,ui,route,id){switch(route){case 'home':return pageHome(state);case 'catalog':return pageCatalog(state,ui);case 'agent':return pageAgent(state,ui,id);case 'activity':return pageActivity(state,ui);case 'rules':return pageRules(state,ui);case 'approvals':return pageApprovals(state);case 'spending':return pageSpending(state);case 'audit':return pageAudit(state,ui);case 'integrations':return pageIntegrations(state,ui);default:return pageNotFound();}}
const integrationInstructions={
 A:{title:'Monitor AI requests',lead:'Start here. Your agent routes model calls through the gateway.',steps:[['Create an agent','Give the agent a name and an owner in Catalog.'],['Copy its credentials','In the real product, the token is shown once. Never commit credentials.'],['Change the model endpoint','Use the gateway URL and this agent’s token in your model client.']],snippet:'// Example only — these are not live credentials\nBASE_URL=https://your-gateway.example/inference/v1\nAPI_KEY=<agent-token-from-secure-onboarding>',limit:'A sees model requests and declared tool intentions. It does not automatically intercept tools running locally.'},
 B:{title:'Control tool execution',lead:'Choose this when the actual tool call must be checked before it runs.',steps:[['Register tool destinations','Add an MCP server or tool target operated by your organization.'],['Route tools through the gateway','Update your agent to call the registered MCP gateway.'],['Verify each tool','Confirm which tools go through B; local tools remain outside its control.']],snippet:'// Example only — not an active connection\nMCP_URL=https://your-gateway.example/mcp\nAUTH=Bearer <same-agent-token>',limit:'Without B, A can see the model request a tool, but may not observe or block its later execution. B is optional and may need client code changes.'},
 C:{title:'Identify users',lead:'Connect identity only when you need user-specific authorization or spending.',steps:[['Verify user login','Your application authenticates the person with an OIDC provider.'],['Forward identity','The agent passes that valid user JWT to the gateway.'],['Configure roles','Map verified users to approved permissions.']],snippet:'// Example only — do not hardcode JWT values\nX-Gov-User-Token: <valid-user-oidc-jwt>',limit:'C does not log users in for your application. Your application must authenticate them and propagate identity to requests. Invalid/missing user identity cannot safely be treated as verified.'}
};
const explainerContent={
  rules:{title:'How rules work',lead:'A policy decides what an agent may request or execute.',body:'Observe shows decisions without enforcing the policy itself. Enforce applies configured rules to traffic that passes through the gateway. Some safeguards, such as authentication or limits, can already apply in Observe. Tool execution requires B; user-specific rules require C.'},
  approvals:{title:'How approvals work',lead:'Some actions need a person to decide before they run.',body:'An approved critical tool waits at the MCP gateway (connection B). Another authorized person approves or rejects it. The requesting person cannot approve their own request under the target requirement. In this demo, the role picker only simulates interface permissions.'},
  spending:{title:'What are these numbers?',lead:'Numbers in this preview are invented to demonstrate the interface.',body:'The target product records inference costs and usage per agent via A. Per-person attribution requires verified identity C. A daily budget is not a guarantee against costs incurred outside the inference gateway.'},
  audit:{title:'How audit evidence works',lead:'Each record should answer who, what, when, and why.',body:'The target backend will persist durable records and use S3 Object Lock GOVERNANCE under configured retention. This frontend has synthetic records only. A “sample record” badge must never be mistaken for proof of actual immutable storage.'},
  preset1:{title:'Safe start',lead:'A starting template for broad visibility without breaking existing flows.',body:'In enforcement: approved read/write tools can proceed, critical or unclassified tools are blocked. Discovery mode evaluates certain policy denials without applying them. The real backend also enforces independently configured authentication, limits and filters.'},
  preset2:{title:'Team approval',lead:'Adds differentiated user roles and review of critical tool use.',body:'Write actions require verified eligible user roles (C). Critical execution also needs the tool gateway (B) and human approval. If required connections are absent, affected operations are not silently accepted.'},
  preset3:{title:'Custom access',lead:'Default deny with explicitly configured permissions.',body:'Only named rules allow actions. For critical tools, additional approval conditions still apply. Both the model-intent channel and actual tool-execution channel must be considered separately.'}
};
const evidenceLabel=e=>e.evidence?`<span class="pill mini" data-status="allowed">${I('check',11)}Sample record available</span>`:statusPill('missing',true);
function drawerShell(label,title,content,footer=''){return `<div class="scrim" data-action="close-overlay" aria-hidden="true"></div><aside class="drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title"><header class="drawer-header"><div><span class="drawer-label">${safe(label)}</span><h2 id="drawer-title">${safe(title)}</h2></div><button class="icon-btn soft" data-action="close-overlay" aria-label="Close details">${I('x',19)}</button></header><div class="drawer-body">${content}</div>${footer?`<footer class="drawer-footer">${footer}</footer>`:''}</aside>`;}
export function renderDrawer(state,ui){
  if(!ui.drawer)return '';
  const {kind,id}=ui.drawer;
  if(kind==='event'){
    const e=state.events.find(x=>x.id===id);if(!e)return '';
    const actual=e.kind==='tool'&&e.connections.includes('B');const status=STATUS[e.status]||STATUS.missing;
    const technical=`<details class="mt-4"><summary class="text-link" style="cursor:pointer;font-size:12px">Technical details</summary><div class="mt-4"><dl class="drawer-dl"><dt>Decision</dt><dd>${safe(e.status.toUpperCase())}</dd><dt>Rule</dt><dd>${safe(e.rule)}</dd><dt>Rule version</dt><dd>${safe(e.version)}</dd><dt>Channel</dt><dd>${safe(e.kind==='tool'?'MCP tool':'Inference')}</dd><dt>Model</dt><dd>${safe(e.model)}</dd><dt>Connections</dt><dd>${safe(e.connections.join(' + '))}</dd><dt>Cost</dt><dd>${formatUSD(e.cost)} · sample</dd></dl></div></details>`;
    const steps=[
      ['Request received',`${e.actor} · ${agentName(state,e.agent)}`],
      ['Policy evaluated',`${e.rule} (${e.version})`],
      [status.label,e.reason],
      ['Evidence',e.evidence?'A sample record is available for inspection.':'No evidence was recorded for this example.']
    ];
    const content=`<div class="space-between mb-4">${statusPill(e.status)}<span class="mono muted">${safe(e.id)}</span></div><p class="drawer-lead">${safe(e.reason)}</p><div class="source-note mb-6">This is a synthetic demonstration. No live call was intercepted.</div><h3>What happened</h3><div>${steps.map((s,i)=>`<div class="audit-step"><span class="audit-step-num">${i+1}</span><div><h4>${safe(s[0])}</h4><p>${safe(s[1])}</p></div></div>`).join('')}</div><div class="separator"></div><h3>Record</h3><dl class="drawer-dl"><dt>Agent</dt><dd>${safe(agentName(state,e.agent))}</dd><dt>Time</dt><dd>${safe(e.at)} · sample</dd><dt>Evidence</dt><dd>${evidenceLabel(e)}</dd></dl>${e.kind==='inference'?`<div class="tip mt-4">${I('info',16)}The model requested an action. This is not proof that its tool later executed or was blocked.</div>`:e.kind==='tool'&&!actual?`<div class="tip mt-4">${I('unplug',16)}This tool ran outside connection B. Actual execution is not governed by this gateway.</div>`:''}${technical}`;
    return drawerShell('Decision explained',e.action,content,`${btn('Copy trace ID','copy-trace',{icon:'copy',data:`data-value="${safe(e.id)}"`})}${btn('Done','close-overlay',{variant:'primary'})}`);
  }
  if(kind==='connection'){
    const c=integrationInstructions[id];if(!c)return '';
    return drawerShell(`Connection ${safe(id)}`,c.title,`<p class="drawer-lead">${safe(c.lead)}</p><div class="step-list mt-6">${c.steps.map(([t,d],i)=>`<div class="step"><span class="step-number">${i+1}</span><div class="step-main"><strong>${safe(t)}</strong><p>${safe(d)}</p></div></div>`).join('')}</div><h3>Example setup</h3><div class="code-box"><pre>${safe(c.snippet)}</pre><button class="copy-code" data-action="copy-connection" data-id="${safe(id)}">${I('copy',12)} Copy</button></div><div class="tip">${I('info',16)}<span>${safe(c.limit)}</span></div>`,btn('Close','close-overlay',{variant:'primary'}));
  }
  if(kind==='explainer'){
    const x=explainerContent[id];if(!x)return '';
    return drawerShell('Good to know',x.title,`<p class="drawer-lead">${safe(x.lead)}</p><p>${safe(x.body)}</p><div class="tip mt-6">${I('info',16)}Demo behavior is for illustration. Backend enforcement and identity verification are not implemented here.</div>`,btn('Got it','close-overlay',{variant:'primary'}));
  }
  if(kind==='settings'){
    return drawerShell('Customize the workspace','Appearance',`<p class="drawer-lead">A calm interface that feels like yours.</p><h3>Color palette</h3><div class="theme-grid">${[['forest','Forest'],['violet','Violet'],['ocean','Ocean']].map(([id,label])=>`<button data-action="theme" data-value="${id}" class="theme-option ${state.theme===id?'active':''}" aria-pressed="${state.theme===id}"><div class="theme-swatch ${id}"></div>${label}</button>`).join('')}</div><h3>Appearance</h3><div class="flex gap-2">${btn('Light','appearance',{variant:state.appearance==='light'?'primary':'',icon:'sun',data:'data-value="light"'})}${btn('Dark','appearance',{variant:state.appearance==='dark'?'primary':'',icon:'moon',data:'data-value="dark"'})}</div><hr><h3>Demo controls</h3><p>Reset sample actions, agent settings and approvals to their initial state.</p>${btn('Reset the demo','reset-request',{icon:'refresh'})}<p class="source-note mt-6">Design tokens are defined in <code>src/styles/tokens.css</code>. Palette and appearance preferences are saved in this browser.</p>`,btn('Done','close-overlay',{variant:'primary'}));
  }
  if(kind==='help'){
    return drawerShell('About the product preview','A guided, interactive demo',`<p class="drawer-lead">Explore what agent governance could feel like, without connecting anything.</p><div class="step-list"><div class="step"><span class="step-number">${I('eye',15)}</span><div class="step-main"><strong>Everything is simulated</strong><p>Events, costs, identities, approvals and keys are examples.</p></div></div><div class="step"><span class="step-number">${I('users',15)}</span><div class="step-main"><strong>Try different roles</strong><p>The top menu changes available controls. It is not real authentication.</p></div></div><div class="step"><span class="step-number">${I('layers',15)}</span><div class="step-main"><strong>Read the important details when needed</strong><p>Open a decision to see its rule, evidence and connection limits.</p></div></div></div><div class="separator"></div><p class="micro">This independent visual prototype is based on the architecture and requirements of <a class="text-link" target="_blank" rel="noopener noreferrer" href="https://github.com/enzo-loren/agentic-ai-governance-platform">Agentic AI Governance Platform ${I('external',12)}</a>. It does not implement security controls or verify backend behavior.</p>`,`${btn('Start tour','tour-start',{icon:'play'})}${btn('Close','close-overlay',{variant:'primary'})}`);
  }
  return '';
}
function modalShell(title,iconName,content,buttons){return `<div class="scrim" data-action="close-overlay" aria-hidden="true"></div><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-card"><div class="modal-icon">${I(iconName,22)}</div><h2 id="modal-title">${safe(title)}</h2>${content}${buttons}</div></div>`;}
export function renderModal(state,ui){
  if(!ui.modal)return '';
  const m=ui.modal;
  if(m.kind==='add-agent'){
    return modalShell('Add an agent','plus',`<p>Give this agent a name and an owner. We’ll create a sample connection.</p><form id="new-agent-form"><div class="field-group"><label for="new-agent-name" class="field-label">Agent name</label><input class="field-input" id="new-agent-name" name="name" placeholder="e.g. Research Assistant" maxlength="54" required autofocus></div><div class="field-group"><label for="new-agent-owner" class="field-label">Owner</label><input class="field-input" id="new-agent-owner" name="owner" placeholder="e.g. Taylor Smith" maxlength="54" required></div><div class="modal-actions">${btn('Cancel','close-overlay')}<button class="btn primary" type="submit">Create demo agent ${I('arrow',15)}</button></div></form>`, '');
  }
  if(m.kind==='new-agent-key')return modalShell('Sample connection created','key',`<p>This is a <strong>demo-only key</strong>. It cannot authenticate with any service. Close this window to hide it.</p><div class="code-box"><pre>BASE_URL=https://demo.invalid/inference/v1\nAPI_KEY=demo-not-valid-${safe(m.id||'new-agent')}</pre><button class="copy-code" data-action="copy-demo-key" data-id="${safe(m.id)}">${I('copy',12)} Copy</button></div><div class="source-note">A real key would be a secret shown once, stored only as a hash and revoked securely. This prototype has no credential backend.</div>`, `<div class="modal-actions">${btn('Open agent','navigate',{variant:'primary',data:`data-route="agent/${safe(m.id)}"`})}</div>`);
  if(m.kind==='policy-change'){
    const a=agentById(state,m.id);const policy=POLICY_PRESETS.find(p=>p.id===m.preset);if(!a||!policy)return '';
    return modalShell('Change the active policy?','shield-check',`<p><strong>${safe(policy.name)}</strong> will replace the current policy on ${safe(a.name)}.</p><div class="tip">${I('info',16)}<span>${safe(policy.summary)} This is only a local demo change.</span></div>`,`<div class="modal-actions">${btn('Cancel','close-overlay')}${btn('Apply demo policy','confirm-preset',{variant:'primary',data:`data-id="${safe(a.id)}" data-value="${policy.id}"`})}</div>`);
  }
  if(m.kind==='enforce'){
    const a=agentById(state,m.id);if(!a)return '';
    const enforce=a.mode!=='enforce';const impact=previewImpact(state,m.id);
    return modalShell(enforce?'Turn on enforcement?':'Return to Observe?',enforce?'shield':'eye',`<p>${enforce?`Rules will start denying matching requests that pass through the gateway for ${safe(a.name)}.`:`Policy decisions will be shown, not enforced, for ${safe(a.name)}. Some basic controls still run.`}</p>${enforce?`<div class="tip">${I('eye',16)}<span><strong>${impact.count} sample requests</strong> would have been blocked. Tool executions outside connection B remain outside control.</span></div>${impact.actions.length?`<div class="modal-list">${impact.actions.slice(0,2).map(t=>`<span>${safe(t)}</span>`).join('')}</div>`:''}`:''}<div class="source-note">This changes local demo state only. No real agent traffic is affected.</div>`, `<div class="modal-actions">${btn('Cancel','close-overlay')}${btn(enforce?'Turn on demo enforcement':'Switch to Observe','confirm-mode',{variant:'primary',data:`data-id="${safe(a.id)}" data-value="${enforce?'enforce':'observe'}"`})}</div>`);
  }
  if(m.kind==='pause'){
    const a=agentById(state,m.id);if(!a)return '';
    const pause=a.mode!=='suspended';return modalShell(pause?'Pause this agent?':'Resume this agent?',pause?'pause':'play',`<p>${pause?'The demo will reject this agent’s gateway requests until it resumes. Actions outside the gateway cannot be stopped here.':'This demo agent will return to Observe mode. Confirm its rules before turning on enforcement again.'}</p><div class="source-note">Simulation only · ${safe(a.name)}</div>`,`<div class="modal-actions">${btn('Cancel','close-overlay')}${btn(pause?'Pause demo agent':'Resume demo agent','confirm-pause',{variant:pause?'danger':'primary',data:`data-id="${safe(a.id)}"`})}</div>`);
  }
  if(m.kind==='approval'){
    const a=state.approvals.find(a=>a.id===m.id);if(!a)return '';
    return modalShell(m.decision==='approved'?'Approve this action?':'Reject this action?',m.decision==='approved'?'check-circle':'slash',`<p><strong>${safe(a.action)}</strong><br>${safe(a.reason)}</p><div class="source-note">Requested by ${safe(a.requestedBy)}. Current demo reviewer: ${safe(DEMO_REVIEWER)}. A different authorized person must decide. Demo action only.</div>`,`<div class="modal-actions">${btn('Cancel','close-overlay')}${btn(m.decision==='approved'?'Approve action':'Reject action','confirm-approval',{variant:m.decision==='approved'?'primary':'danger',data:`data-id="${safe(a.id)}" data-value="${safe(m.decision)}"`})}</div>`);
  }
  if(m.kind==='budget'){
    const a=agentById(state,m.id);if(!a)return '';
    return modalShell('Change daily budget','wallet',`<p>Set a sample daily limit for ${safe(a.name)}. Changes do not affect real models.</p><form id="budget-form"><input type="hidden" name="id" value="${safe(a.id)}"><div class="field-group"><label for="budget-amount" class="field-label">Daily limit (USD)</label><input class="field-input" type="number" id="budget-amount" name="budget" value="${a.budget}" min="1" max="100000" step="1" required autofocus></div><div class="modal-actions">${btn('Cancel','close-overlay')}<button class="btn primary" type="submit">Save demo limit</button></div></form>`, '');
  }
  if(m.kind==='reset')return modalShell('Reset this demo?','refresh',`<p>This returns agents, requests and approvals to their starting sample state. Your palette preference stays the same.</p>`,`<div class="modal-actions">${btn('Cancel','close-overlay')}${btn('Reset sample data','confirm-reset',{variant:'danger'})}</div>`);
  return '';
}
export {integrationInstructions};
